1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	  moonstone: 25,
11	};
12	
13	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
14	const BLOCK_SIZE = 3;
15	const BLOCK_PREMIUM = 60;
16	
17	type Item = { type: string };
18	type Scenario = {
19	  customer: { yearsWithMHPCO: number };
20	  steps: Array<{ op: "quote"; items: Item[] }>;
21	};
22	
23	const countsByType = (items: Item[]): Map<string, number> =>
24	  items.reduce(
25	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
26	    new Map<string, number>(),
27	  );
28	
29	const groupBase = (type: string, count: number): number =>
30	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
31	    ? BLOCK_PREMIUM
32	    : count * BASE_PREMIUM[type];
33	
34	const itemsBase = (items: Item[]): number => {
35	  let total = 0;
36	  for (const [type, count] of countsByType(items)) {
37	    total += groupBase(type, count);
38	  }
39	  return total;
40	};
41	
42	const applyItemSurcharges = (base: number): number =>
43	  base * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
44	
45	const roundUpInFavorOfInsurer = (amount: number): number =>
46	  Math.ceil(Math.round(amount * 1e6) / 1e6);
47	
48	const quotePremium = (items: Item[]): number => {
49	  const premiumBeforeFee = applyItemSurcharges(itemsBase(items));
50	  return roundUpInFavorOfInsurer(premiumBeforeFee + PROCESSING_FEE);
51	};
52	
53	export const runScenario = (scenario: unknown): unknown => ({
54	  results: (scenario as Scenario).steps.map((step) => ({
55	    premium: quotePremium(step.items),
56	  })),
57	});
